"""Drawings of neuronte-wide-supplement-v1, in box units (see train/wide.py).

The wide characters of Supplemental Symbols and Pictographs and of Symbols
and Pictographs Extended-A, each drawn from its Unicode name as a
one-colour pictogram for a box of two cells. Faces are term_rest's faces
put in the box with parts added; the coloured hearts and the red and white
hair are twins of their siblings, by the owner's choice. No font was read.
"""
import math

import term_rest
from wide_parts import *  # noqa: F401,F403

NOTES = {}
DRAWN = {}
TWIN = "told apart from its siblings only by colour: drawn the same as them, twins by the owner's choice"


def d(cp, shapes, note=None):
    if cp in DRAWN:
        raise ValueError(f"U+{cp:04X} drawn twice")
    DRAWN[cp] = shapes
    if note:
        NOTES[cp] = note


# ---------------------------------------------------------------- helpers (own copies: wide_pict is another bundle's source)

def leaf(cx, cy, length, width, angle):
    pts = [(length / 2 * t, width / 2 * (1 - t * t)) for t in [-1 + 2 * i / 20 for i in range(21)]]
    pts += [(length / 2 * t, -width / 2 * (1 - t * t)) for t in [1 - 2 * i / 20 for i in range(1, 20)]]
    a = math.radians(angle)
    return F(*[(cx + x * math.cos(a) - y * math.sin(a), cy + x * math.sin(a) + y * math.cos(a)) for x, y in pts])


def petals(n, cx, cy, dist, r, rot=-90.0):
    return sum((D(cx + dist * math.cos(math.radians(rot + 360.0 * i / n)), cy + dist * math.sin(math.radians(rot + 360.0 * i / n)), r)
                for i in range(n)), [])


def spokes(cx, cy, r0, r1, n, w, start=-90.0):
    out = []
    for i in range(n):
        a = math.radians(start + 360.0 * i / n)
        out += L((cx + r0 * math.cos(a), cy + r0 * math.sin(a)), (cx + r1 * math.cos(a), cy + r1 * math.sin(a)), w=w)
    return out


def spiral(cx, cy, r0, r1, turns, w=1.6):
    n = int(60 * turns)
    return L(*[(cx + (r0 + (r1 - r0) * i / n) * math.cos(2 * math.pi * turns * i / n),
                cy + (r0 + (r1 - r0) * i / n) * math.sin(2 * math.pi * turns * i / n)) for i in range(n + 1)], w=w)


def wave(x0, x1, y, amp, n, w=1.6):
    return L(*[(x0 + (x1 - x0) * i / (12 * n), y - amp * math.sin(2 * math.pi * i / 12)) for i in range(12 * n + 1)], w=w)


def ell(cx, cy, rx, ry, a0=0, a1=360, step=10):
    return [(cx + rx * math.cos(math.radians(a)), cy + ry * math.sin(math.radians(a))) for a in range(a0, a1, step)]


def big_heart():
    return heart(9, 9.6, 15.0)


EYES = ((6.55, 7.2), (11.45, 7.2))   # where term_rest's dot eyes fall in the box (no brows)


def sface(spec, add=(), cut=()):
    """term_rest's face of spec in the box, with box-unit parts cut out of it and added to it.

    Eyes "none": the face is made with dot eyes and the eyes are cut away."""
    if spec[0] == "none":
        spec = ("dot",) + tuple(spec[1:])
        cut = sum((D(x, y, 1.6) for x, y in EYES), []) + list(cut)
    return rest_face(spec) + K(list(cut)) + list(add)


def aface(ears=(), nose=(), extra=(), eyes=((6.6, 9.0), (11.4, 9.0)), r=6.0, cy=10.2, ry=None, eye_r=0.85):
    ry = ry or r
    feat = sum((D(x, y, eye_r) for x, y in eyes), []) + list(nose)
    return list(ears) + K(D(9, cy, r + 0.6, ry + 0.6)) + C(9, cy, r - 0.7, 1.4, ry=ry - 0.7) + feat + list(extra)


def side(body, head, extra=()):
    return fit(list(body) + list(head) + list(extra))


def legs4(xs, y0, y1, w=1.3):
    return sum((L((x, y0), (x, y1), w=w) for x in xs), [])


def medal(n):
    return F((5.0, 1.6), (8.0, 1.6), (10.0, 8.0), (7.4, 8.0)) + F((13.0, 1.6), (10.0, 1.6), (8.0, 8.0), (10.6, 8.0)) + D(9, 11.8, 4.4) + \
        K(text(str(n), 9, 11.9, 4.6, pen=1.1))


HAIR = {"red": None, "curly": None, "bald": None, "white": None}


