def body4(bx=8.0, by=9.0, rx=5.6, ry=3.0, legs=True, leg_w=1.3):
    out = D(bx, by, rx, ry)
    if legs:
        out += legs4((bx - rx * 0.7, bx - rx * 0.4, bx + rx * 0.45, bx + rx * 0.75), by, 15.8, leg_w)
    return out


def bird(beak=((14.6, 6.0), (17.0, 6.6), (14.6, 7.2)), neck=False, legs=True, tail=((3.0, 9.0), (0.6, 6.4), (2.0, 10.6))):
    out = D(8.6, 10.0, 5.0, 3.6) + D(13.4, 6.4, 2.2) + F(*beak) + F(*tail)
    if legs:
        out += L((8.0, 13.4), (7.6, 16.0), w=0.7) + L((10.0, 13.4), (10.4, 16.0), w=0.7)
    return out + K(D(14.0, 5.8, 0.5))


